import sys

def rep_brute(s, k):
    n = len(s)
    best = 0
    for i in range(n):
        cnt = {}
        for j in range(i, n):
            cnt[s[j]] = cnt.get(s[j], 0) + 1
            others = (j - i + 1) - max(cnt.values())
            if others > k: break
            if j - i + 1 > best: best = j - i + 1
    return best

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    k = int(data[1])
    s = data[2] if len(data) > 2 else ''
    print(rep_brute(s, k))

import sys

def rep_opt(s, k):
    cnt = {}
    best = l = 0
    for r, ch in enumerate(s):
        cnt[ch] = cnt.get(ch, 0) + 1
        if r - l + 1 - max(cnt.values()) > k:
            cnt[s[l]] -= 1
            l += 1
        best = max(best, r - l + 1)
    return best

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    k = int(data[1])
    s = data[2] if len(data) > 2 else ''
    print(rep_opt(s, k))
